package com.roadwatch.report;
import java.util.Map; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import org.springframework.web.multipart.MultipartFile;
@Service class PotholeDetector { private final String url,token; PotholeDetector(@Value("${detection.model-url}")String url,@Value("${detection.token}")String token){this.url=url;this.token=token;} Detection detect(MultipartFile file){if(url.isBlank())return new Detection(.72,Severity.MEDIUM); try{Map response=RestClient.create().post().uri(url).header(HttpHeaders.AUTHORIZATION,"Bearer "+token).contentType(MediaType.APPLICATION_OCTET_STREAM).body(file.getResource()).retrieve().body(Map.class);double confidence=Double.parseDouble(String.valueOf(response.getOrDefault("confidence",response.getOrDefault("score",.72))));String label=String.valueOf(response.getOrDefault("severity","MEDIUM"));return new Detection(confidence,Severity.valueOf(label.toUpperCase()));}catch(Exception ignored){return new Detection(.72,Severity.MEDIUM);}} record Detection(double confidence,Severity severity){} }
